/// <summary>
/// Data contract class for transfer picking list generation service task
/// </summary>
[DataContractAttribute]
class METTransferPickingListGenerationTaskContract
{
    container               oscCodeList;
    InventTransferId        transferId;

}

Method.Source:
    /// <summary>
    /// OSCCode list which contains the list of OSCCode need to be processed
    /// </summary>
    /// <param name = "_oscCodeList">OSCCode list</param>
    /// <returns>OSCCode list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmOSCCodeList(container _oscCodeList = oscCodeList)
    {
        oscCodeList = _oscCodeList;

        return oscCodeList;
    }

    /// <summary>
    /// Transfer Id which need to be processed
    /// </summary>
    /// <param name = "_transferId">Transfer Id</param>
    /// <returns>Transfer Id</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public InventTransferId parmTransferId(InventTransferId _transferId = transferId)
    {
        transferId = _transferId;

        return transferId;
    }

    /// <summary>
    /// get Caption for the batch job task based on transfer id and OSC code
    /// </summary>
    /// <returns>batch job caption</returns>
    public str getCaption()
    {
        int i;
        str caption = strFmt('%1 - ', this.parmTransferId());

        for(i = 1; i <= conLen(this.parmOSCCodeList()); i++)
        {
            if(i != 1)
            {
                caption += ', ';
            }
            caption += conPeek(this.parmOSCCodeList(), i);
        }
        return caption;
    }
